import org.junit.Test;
import org.jsoup.Connection;
import org.jsoup.helper.HttpConnection;

import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class HttpConnectionTest {

    @Test
    public void connectStringTest() {
        Connection connection = HttpConnection.connect("http://example.com");
        assertEquals("http://example.com", connection.request().url().toString());
    }

    @Test
    public void connectURLTest() throws Exception {
        Connection connection = HttpConnection.connect(new URL("http://example.com"));
        assertEquals("http://example.com", connection.request().url().toString());
    }

    @Test
    public void urlURLTest() throws Exception {
        HttpConnection httpConnection = new HttpConnection();
        Connection connection = httpConnection.url(new URL("http://example.com"));
        assertEquals("http://example.com", connection.request().url().toString());
    }

    @Test
    public void urlStringTest() {
        HttpConnection httpConnection = new HttpConnection();
        Connection connection = httpConnection.url("http://example.com");
        assertEquals("http://example.com", connection.request().url().toString());
    }

    @Test
    public void proxyTest() {
        HttpConnection httpConnection = new HttpConnection();
        Connection connection = httpConnection.proxy("localhost", 8080);
        assertEquals("localhost", connection.request().proxy().getHost());
        assertEquals(8080, connection.request().proxy().getPort());
    }

    @Test
    public void userAgentTest() {
        HttpConnection connection = new HttpConnection();
        String agent = "Mozilla";
        Connection result = connection.userAgent(agent);
        assertEquals(agent, result.request().userAgent());
    }

    @Test
    public void timeoutTest() {
        HttpConnection connection = new HttpConnection();
        int millis = 10000;
        Connection result = connection.timeout(millis);
        assertEquals(millis, result.request().timeout());
    }

    @Test
    public void maxBodySizeTest() {
        HttpConnection connection = new HttpConnection();
        int bytes = 1024;
        Connection result = connection.maxBodySize(bytes);
        assertEquals(bytes, result.request().maxBodySize());
    }
    @Test
    public void dataStringTest() {
        HttpConnection httpConnection = new HttpConnection();
        Connection connection = httpConnection.data("key", "value");
        assertEquals("value", connection.request().data().get(0).value());
    }

    @Test
    public void dataInputStreamTest() {
        HttpConnection httpConnection = new HttpConnection();
        InputStream is = new ByteArrayInputStream("test-file-content".getBytes());
        Connection connection = httpConnection.data("key", "filename", is);
        assertEquals("filename", connection.request().data().get(0).key());
    }

    @Test
    public void dataMapTest() {
        HttpConnection httpConnection = new HttpConnection();
        Map<String, String> data = new HashMap<>();
        data.put("key", "value");
        Connection connection = httpConnection.data(data);
        assertEquals("value", connection.request().data().get(0).value());
    }

    @Test
    public void headersTest() {
        HttpConnection connection = new HttpConnection();
        Map<String, String> headers = new HashMap<>();
        headers.put("name", "value");
        Connection result = connection.headers(headers);
        assertEquals(headers, result.request().headers());
    }

    @Test
    public void cookieTest() {
        HttpConnection connection = new HttpConnection();
        String name = "cookieName";
        String value = "cookieValue";
        Connection result = connection.cookie(name, value);
        assertEquals(value, result.request().cookies().get(name));
    }

    @Test
    public void cookiesTest() {
        HttpConnection connection = new HttpConnection();
        Map<String, String> cookies = new HashMap<>();
        cookies.put("name", "value");
        Connection result = connection.cookies(cookies);
        assertEquals(cookies, result.request().cookies());
    }
}
